<script>

// ============================================================
// PROJECT AETHER BLOCKCHAIN CONFIGURATION
// ============================================================

const RPC_URL =
    "https://base-sepolia.g.alchemy.com/v2/alch_wE4l5QcffNreB_ZahJm1m";

const CONTRACT_ADDRESS =
    "0xA3FFBC19730222a2C0a85e65791B890B4ecd6C26";

const ABI = [
    "function getFileCid(string _rawPin) view returns (string)"
];

// ============================================================
// UI helpers
// ============================================================

const statusElement =
    document.getElementById("status");

const debugElement =
    document.getElementById("debug");

const log = (
    message,
    ok = false
) => {

    statusElement.textContent = message;

    statusElement.className =
        "status " + (ok ? "ok" : "");

};

const debug = (
    message
) => {

    debugElement.textContent =
        message;

};

// ============================================================
// SHA-256
// ============================================================

async function sha256OfBlob(blob) {

    const buffer =
        await blob.arrayBuffer();

    const hash =
        await crypto.subtle.digest(
            "SHA-256",
            buffer
        );

    return "0x" +
        Array
            .from(
                new Uint8Array(hash)
            )
            .map(
                b =>
                    b.toString(16)
                    .padStart(2, "0")
            )
            .join("");

}

// ============================================================
// Configuration validation
// ============================================================

function validConfig() {

    return (
        !RPC_URL.includes("YOUR_") &&
        !CONTRACT_ADDRESS.includes("YOUR_")
    );

}

// ============================================================
// Main verification function
// ============================================================

async function run() {

    const pin =
        document
            .getElementById("pin")
            .value
            .trim();

    // --------------------------------------------
    // Validate PIN
    // --------------------------------------------

    if (!/^\d{4}$/.test(pin)) {

        log(
            "Enter exactly 4 digits."
        );

        return;
    }

    // --------------------------------------------
    // Validate config
    // --------------------------------------------

    if (!validConfig()) {

        log(
            "Dashboard is not configured.\n" +
            "Add the Alchemy RPC URL and contract address in index_html.h."
        );

        return;
    }

    // --------------------------------------------
    // Check ethers.js
    // --------------------------------------------

    if (
        typeof ethers === "undefined"
    ) {

        log(
            "FAILED ❌\n" +
            "ethers.js did not load.\n" +
            "Check phone Internet access."
        );

        return;
    }

    try {

        // ----------------------------------------
        // Step 1
        // ----------------------------------------

        log(
            "1/4 Preparing request…"
        );

        // ----------------------------------------
        // Step 2
        // ----------------------------------------

        log(
            "2/4 Asking Base Sepolia for the file record…"
        );

        const provider =
            new ethers.providers.JsonRpcProvider(
                RPC_URL
            );

        const contract =
            new ethers.Contract(
                CONTRACT_ADDRESS,
                ABI,
                provider
            );

        const cid = await contract.getFileCid(pin);

        if (!cid || cid === "") {

            throw new Error(
                "PIN not found"
            );

        }

        debug("CID: " + cid);

        // ----------------------------------------
        // Step 3
        // ----------------------------------------

        log(
            "3/4 Downloading the file from IPFS…"
        );

        const url =
            "https://ipfs.io/ipfs/" + cid;

        const response =
            await fetch(url);

        if (!response.ok) {

            throw new Error(
                "IPFS download failed: HTTP " +
                response.status
            );

        }

        const blob =
            await response.blob();

        // ----------------------------------------
        // Step 4 - Download (on-chain integrity check skipped: old contract version)
        // ----------------------------------------

        const objectUrl =
            URL.createObjectURL(blob);

        const anchor =
            document.createElement("a");

        anchor.href =
            objectUrl;

        anchor.download =
            "aether_payload.zip";

        document.body.appendChild(anchor);

        anchor.click();

        anchor.remove();

        URL.revokeObjectURL(
            objectUrl
        );

        // ----------------------------------------
        // SUCCESS
        // ----------------------------------------

        log(
            "DOWNLOADED ✅\n" +
            "File: aether_payload.zip\n" +
            "Size: " + blob.size + " bytes\n" +
            "Note: On-chain SHA-256 check skipped (old contract version).",
            true
        );

    } catch (error) {

        console.error(error);

        log(
            "FAILED ❌\n" +
            (
                error?.reason ||
                error?.message ||
                String(error)
            )
        );

    }

}

// ============================================================
// Button
// ============================================================

document
    .getElementById("go")
    .addEventListener(
        "click",
        run
    );

// ============================================================
// Startup diagnostic
// ============================================================

setTimeout(() => {

    if (
        typeof ethers === "undefined"
    ) {

        debug(
            "ethers.js NOT loaded. " +
            "Check phone Internet access."
        );

    } else {

        debug(
            "ethers.js loaded successfully."
        );

    }

}, 1000);

</script>

