## Firmware (Single File, Flash in 30 Seconds)

```cpp
// tactical_node.ino — Flash via Arduino IDE or PlatformIO
// Board: "ESP32S3 Dev Module", USB CDC On Boot: Enabled

#include <WiFi.h>
#include <WebServer.h>
#include <DNSServer.h>
#include <ESPmDNS.h>
#include <ArduinoJson.h>

const char* AP_SSID = "Aether-Node";
const char* AP_PASS = "aether1234";
const char* MDNS_NAME = "aether-node";

WebServer server(80);
DNSServer dnsServer(53);

// Minimal log buffer (RAM only, lost on reboot)
struct LogEntry { char timestamp[20]; char event[32]; };
LogEntry logs[10];
int logCount = 0;

void addLog(const char* event) {
  if (logCount >= 10) return;
  time_t now = time(nullptr);
  strftime(logs[logCount].timestamp, 20, "%Y-%m-%d %H:%M:%S", localtime(&now));
  strncpy(logs[logCount].event, event, 31);
  logCount++;
}

void setup() {
  Serial.begin(115200);
  delay(500);

  // WiFi AP
  WiFi.mode(WIFI_AP);
  WiFi.softAP(AP_SSID, AP_PASS);
  dnsServer.start(53, "*", WiFi.softAPIP());

  // mDNS
  MDNS.begin(MDNS_NAME);
  MDNS.addService("http", "tcp", 80);

  // Routes
  server.on("/", HTTP_GET, handleDashboard);
  server.on("/api/files", HTTP_GET, handleFileList);
  server.on("/api/preview", HTTP_GET, handlePreview);
  server.on("/api/logs", HTTP_GET, handleLogs);
  server.onNotFound([]() { server.sendHeader("Location", "/"); server.send(302); });

  server.begin();
  addLog("session_start");
  Serial.println("Tactical Node ready. AP: " + String(AP_SSID));
}

void loop() {
  dnsServer.processNextRequest();
  server.handleClient();
}

void handleDashboard() {
  String html = R"rawliteral(
<!doctype html><html><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Aether Tactical</title>
<style>
body{font-family:system-ui;margin:0;background:#0a0f14;color:#eef2f6;min-height:100vh;padding:20px}
.card{max-width:600px;margin:0 auto;background:#121923;border:1px solid #2b3948;border-radius:16px;padding:24px}
h1{font-size:20px;margin:0 0 16px}.file{display:flex;justify-content:space-between;align-items:center;padding:12px;border-bottom:1px solid #2b3948}
.file:last-child{border:none}.info{display:flex;flex-direction:column}.name{font-weight:600}.meta{font-size:12px;color:#94a3b2}
button{padding:8px 16px;border:none;border-radius:8px;background:#36b37e;color:#07140f;font-weight:600;cursor:pointer}
button.secondary{background:#2b3948;color:#eef2f6;margin-left:8px}
.preview{margin-top:16px;padding:16px;background:#0b1118;border-radius:12px;max-height:60vh;overflow:auto}
img{max-width:100%}.pdf{width:100%;height:500px;border:none}
</style></head><body>
<div class="card"><h1>📁 Aether Tactical — File Preview</h1>
<div id="files">Loading...</div>
<div id="preview" class="preview" style="display:none"></div>
</div>
<script>
async function loadFiles() {
  const res = await fetch('/api/files');
  const data = await res.json();
  document.getElementById('files').innerHTML = data.files.map(f => `
    <div class="file">
      <div class="info"><span class="name">${f.name}</span><span class="meta">${f.size} bytes • ${f.type}</span></div>
      <div>
        <button onclick="preview('${f.cid}','${f.type}','${f.name}')">Preview</button>
        <button class="secondary" onclick="download('${f.cid}','${f.name}')">Download</button>
      </div>
    </div>`).join('');
}
async function preview(cid, type, name) {
  const url = `https://gateway.pinata.cloud/ipfs/${cid}`;
  const prev = document.getElementById('preview');
  prev.style.display = 'block';
  if (type.startsWith('image/')) {
    prev.innerHTML = `<strong>${name}</strong><br><img src="${url}" alt="preview">`;
  } else if (type === 'application/pdf') {
    prev.innerHTML = `<strong>${name}</strong><br><iframe class="pdf" src="${url}"></iframe>`;
  } else {
    const res = await fetch(url);
    const text = await res.text();
    prev.innerHTML = `<strong>${name}</strong><br><pre style="white-space:pre-wrap">${text}</pre>`;
  }
}
async function download(cid, name) {
  const url = `https://gateway.pinata.cloud/ipfs/${cid}`;
  const a = document.createElement('a'); a.href = url; a.download = name; a.click();
}
loadFiles();
</script></body></html>)rawliteral";
  server.send(200, "text/html", html);
}

void handleFileList() {
  // In production: query Base Sepolia via Alchemy for file list
  // For demo: static list
  String json = R"({"files":[{"cid":"bafkreibljtkfhndytktic6tay36odejx4fd4zjkztnlnotppxu4ell5rcu","name":"intel_report.pdf","size":245760,"type":"application/pdf"},{"cid":"bafkreia2ndexamplecidhere","name":"target_photo.jpg","size":1024000,"type":"image/jpeg"}]})";
  server.send(200, "application/json", json);
}

void handlePreview() {
  // Not needed — preview happens client-side via IPFS gateway
  server.send(404);
}

void handleLogs() {
  String json = "{\"logs\":[";
  for (int i = 0; i < logCount; i++) {
    json += "{\"time\":\"" + String(logs[i].timestamp) + "\",\"event\":\"" + String(logs[i].event) + "\"}";
    if (i < logCount - 1) json += ",";
  }
  json += "]}";
  server.send(200, "application/json", json);
}
```

