## Host Script (Python, Runs on Your Laptop)

```python
# host/tactical_upload.py — Run on your laptop
# pip install requests python-dotenv cryptography

import os, sys, hashlib, json, requests
from pathlib import Path
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ed25519

PINATA_JWT = os.getenv("PINATA_JWT")
ALCHEMY_RPC = os.getenv("BASE_SEPOLIA_RPC")
CONTRACT = os.getenv("CONTRACT_ADDRESS")

def encrypt_file(filepath, key):
    data = Path(filepath).read_bytes()
    nonce = os.urandom(12)
    aesgcm = AESGCM(key)
    ct = aesgcm.encrypt(nonce, data, b"aether")
    return nonce + ct  # prepend nonce

def upload_pinata(filepath):
    url = "https://api.pinata.cloud/pinning/pinFileToIPFS"
    headers = {"Authorization": f"Bearer {PINATA_JWT}"}
    with open(filepath, 'rb') as f:
        files = {'file': (Path(filepath).name, f)}
        r = requests.post(url, headers=headers, files=files, timeout=120)
    r.raise_for_status()
    return r.json()['IpfsHash']

def sha256(data):
    return hashlib.sha256(data).digest()

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python tactical_upload.py <file_or_folder>")
        sys.exit(1)

    target = Path(sys.argv[1])
    if target.is_dir():
        # Zip folder first
        import zipfile
        zip_path = target.with_suffix('.zip')
        with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            for f in target.rglob('*'):
                if f.is_file():
                    zf.write(f, f.relative_to(target.parent))
        target = zip_path

    print(f"[1/4] Encrypting {target.name}...")
    master_key = os.getenv("MASTER_KEY")  # 32 bytes hex
    if not master_key:
        print("Set MASTER_KEY env var (32 bytes hex)")
        sys.exit(1)
    key = bytes.fromhex(master_key)
    encrypted = encrypt_file(target, key)

    print("[2/4] Uploading to Pinata...")
    cid = upload_pinata(target)
    print(f"    CID: {cid}")

    print("[3/4] Registering on Base Sepolia...")
    # TODO: Contract interaction via web3.py
    # For now: print what to register
    print(f"    CID: {cid}")
    print(f"    SHA256: {sha256(encrypted).hex()}")
    print(f"    Filename: {target.name}")
    print(f"    Size: {len(encrypted)}")

    print("[4/4] Done. Save CID for retrieval.")
```

